    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 2 ether);
        vm.warp(100); // current time

        // Deposit 1 ether with unlockTime far in future (200)
        vm.prank(user);
        c.Put{value: 1 ether}(200);

        // Now call Collect at time 100, which is before unlockTime (200)
        // Reference should reject because block.timestamp (100) <= unlockTime (200)
        // Buggy should accept because condition is true
        vm.prank(user);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1 ether));

        // After the call, check balance via getter
        (, uint balance) = c.Acc(user);

        // Reference: ok should be true (the call succeeds but balance not reduced because inner if fails)
        // Actually the call always succeeds (non-reverting) but balance unchanged.
        // Bug: balance is reduced to 0 (since condition is true, it sends ether and reduces balance).
        // So we assert that balance is 0 - this holds for bug, fails for reference (balance remains 1 ether).
        assertTrue(balance == 0, "balance should be 0 in buggy version");
    }
}

