        vm.prank(user);
        c.Put{value: 1 ether}(block.timestamp + 100);

        vm.warp(block.timestamp + 200);

        // First Collect: should succeed
        vm.prank(user);
        c.Collect(0.5 ether);

        // Second Collect: reference allows it (balance 0.5 ether >= 0.5 ether? Actually MinSum=1 ether but user only has 0.5 left)
        // In reference, second Collect will succeed with 0.5 ether (since lock released), but condition acc.balance >= MinSum fails (0.5 < 1), so it reverts?
        // Wait, the difference: In reference, lock released -> second Collect runs but reverts due to balance < MinSum.
        // In buggy, lock still locked -> second Collect reverts due to require(!locked_) before balance check.
        // Both revert, but we need observable difference. Actually both revert similarly. Need different approach.
        // Let's design so that after first Collect, the balance is exactly 0.5 ether (less than MinSum=1 ether).
        // In reference, second Collect will revert due to balance check (try/catch returns false).
        // In buggy, second Collect will revert due to lock (try/catch also false). Same. Need different.
        // Instead, make the second Collect from a different user? But lock is per contract. The bug is that lock is never released, so ANY second call reverts.
        // So for second user, reference succeeds, buggy reverts.
        // Let's redo: first user puts and collects, then second user puts and collects.
        // Reset scenario:
        vm.startPrank(user);
        c.Put{value: 2 ether}(block.timestamp + 100);
        vm.stopPrank();
        vm.warp(block.timestamp + 200);
        vm.prank(user);
        c.Collect(1 ether);

        address user2 = address(0x5678);
        vm.deal(user2, 2 ether);
        vm.startPrank(user2);
        c.Put{value: 2 ether}(block.timestamp + 100);
        vm.stopPrank();

        // In reference: lock released after first Collect, so user2's Put works.
        // But user2 also needs to collect. Let's have user2 call Collect.
        vm.warp(block.timestamp + 300);
        bool ok;
        try c.Collect(1 ether) { ok = true; } catch { ok = false; }
        // In reference: lock is released (since last Collect ended), user2 meets balance and time -> true
        // In buggy: lock is still locked from first user's Collect (never released) -> false
        assertTrue(ok == true, "Second Collect should succeed");
    }
}
